def ampm(hm):
    h, m = map(int, hm.split(':'))
    part = 'காலை' if h < 12 else 'மதியம்' if h < 16 else 'மாலை'
    return f'{part} {((h + 11) % 12) + 1}:{m:02d}'


def span(a, b):
    pa, pb = ampm(a), ampm(b)
    return f'{pa} – {pb.split(" ")[1]}' if pa.split(' ')[0] == pb.split(' ')[0] else f'{pa} – {pb}'


def minus36(hm):
    h, m = map(int, hm.split(':'))
    t = h * 60 + m - 36
    return f'{t // 60:02d}:{t % 60:02d}'


# ---------------------------------------------------------------- drawings
def mandala(size=330, labels=True, fill=None, mark=None):
    """The 3×3 Vastu grid with north at the top: names, elements and guardians, in each zone's colour."""
    c, o = size / 3, 34
    W = size + 2 * o
    out = f'<svg class="vmand" viewBox="0 0 {W} {W}" role="img" aria-label="வாஸ்து மண்டலம்: மேலே வடக்கு">'
    for r, row in enumerate(GRID):
        for q, z in enumerate(row):
            Z = ZONES[z]
            x, y = o + q * c, o + r * c
            out += f'<rect x="{x}" y="{y}" width="{c}" height="{c}" fill="{(fill or {}).get(z, Z["col"][0][1])}" stroke="#b8862b" stroke-width="1.5"/>'
            sub = (fill and (mark or {}).get(z)) or (Z['el'] or Z['god'].split(' (')[0])
            out += (f'<text x="{x + c / 2}" y="{y + c / 2 - 6}" text-anchor="middle" font-size="15" font-weight="700" fill="#5a1a0c">{esc(Z["name"])}</text>'
                    + ''.join(f'<text x="{x + c / 2}" y="{y + c / 2 + 16 + j * 16}" text-anchor="middle" font-size="11.5" fill="#7a5a3a">{esc(part)}</text>' for j, part in enumerate(sub.split(' · '))))
    if labels:
        m = W / 2
        out += (f'<text x="{m}" y="22" text-anchor="middle" font-size="15" font-weight="700" fill="#6e1216">▲ வடக்கு</text>'
                f'<text x="{m}" y="{W - 9}" text-anchor="middle" font-size="15" font-weight="700" fill="#6e1216">தெற்கு</text>'
                f'<text x="{W - 12}" y="{m}" text-anchor="middle" font-size="15" font-weight="700" fill="#6e1216" transform="rotate(90 {W - 12} {m})">கிழக்கு</text>'
                f'<text x="12" y="{m}" text-anchor="middle" font-size="15" font-weight="700" fill="#6e1216" transform="rotate(-90 12 {m})">மேற்கு</text>')
    return out + '</svg>'


def facing_plan(f):
    """The ideal layout for a facing house, with the road and the auspicious stretch for the door."""
    F = FACING[f]
    size, o = 330, 34
    W = size + 2 * o
    svg = mandala(size, labels=True, fill={z: '#fffaf0' for z in ZONES}, mark=IDEAL)
    # road band on the facing side, and the door stretch (padas counted as in VastuPlan)
    road = {'N': (o, 2, size, 18), 'S': (o, W - 20, size, 18), 'E': (W - 20, o, 18, size), 'W': (2, o, 18, size)}[F['c']]
    a, b = {'E': (2 / 8, 4 / 8), 'S': (2 / 8, 4 / 8), 'W': (2 / 8, 5 / 8), 'N': (2 / 8, 5 / 8)}[F['c']]
    if F['c'] == 'E':
        door = (W - o - 5, o + a * size, 10, (b - a) * size)
    elif F['c'] == 'S':
        door = (o + size - b * size, W - o - 5, (b - a) * size, 10)
    elif F['c'] == 'W':
        door = (o - 5, o + size - b * size, 10, (b - a) * size)
    else:
        door = (o + a * size, o - 5, (b - a) * size, 10)
    rd = f'<rect x="{road[0]}" y="{road[1]}" width="{road[2]}" height="{road[3]}" rx="4" fill="#8a8073" opacity=".45"/>'
    dr = f'<rect x="{door[0]}" y="{door[1]}" width="{door[2]}" height="{door[3]}" rx="3" fill="#b3201f"/>'
    i = svg.index('>') + 1
    return svg[:i] + rd + svg[i:].replace('</svg>', dr + '</svg>')


